

class CbamException(Exception):
    """ Base exception for every exceptions in taf.cloud.cbam library. """


class ClientException(CbamException):
    pass


class VnfmApiNotSupported(Exception):
    """ VNFM API in given version is not supported """


class SessionException(CbamException):
    """ Base exception for session related problems """


class VnfNameNotFoundException(CbamException):
    """Exception when VNF name not found"""


class UnsupportedVimInfoType(CbamException):
    """Exception when given VIM info type isn't supported"""


class SessionNotConnectedException(SessionException):
    """ Raises when connect wasn't used before use of session  """


class ClientErrorException(CbamException):
    """ Base exception for HTTP client errors """


class ServerErrorException(CbamException):
    """ Base exception for HTTP server errors """


class BadRequestException(ClientErrorException):
    """ 400 Bad Request - Required information for the request was missing or had syntactical errors. """


class UnauthorizedException(ClientErrorException):
    """ 401 Unauthorized - Client is required to include valid credentials in the request. """


class ForbiddenAccessException(ClientErrorException):
    """ 403 Forbidden - Access to the requested (valid) URL by the client is Forbidden for some reason.
    (The server understood the request, but will not fulfill it due to client related issues) """


class NotFoundException(ClientErrorException):
    """ 404 Not Found - The requested URI does not exist. """


class MethodNotAllowedException(ClientErrorException):
    """ 405 Method Not Allowed - The HTTP method is not valid for the URI. """


class NotApplicableException(ClientErrorException):
    """ 406 Not Applicable - Accept header is incorrect for the resource or requests different format than
    JSON or XML. """


class ConflictException(ClientErrorException):
    """ 409 Conflict - Another request is in progress that prohibits the fulfillment of the current request,
    or the current resource state is inconsistent with the request. """


class UnprocessableEntityException(ClientErrorException):
    """ 422 Unprocessable Entity - Input information for the request contains semantic errors. """


class InternalServerErrorException(ServerErrorException):
    """ 500 Internal Server Error - Server is unable to process the request. """


class ServiceUnavailableException(ServerErrorException):
    """ 503 Service Unavailable - Server is unable to process the request due to internal overload. """


class VersionNotSupported(CbamException):
    """ Requested API version is not supported """


class VnfdidPkgNotFound(CbamException):
    """ Requested Catalog vnfd_id not found in CBAM """
